      "body": "୨୦୨୩ ରେ, କଂଗ୍ରେସ ୩୯.୪% ଭୋଟ୍ ପାଇ ୬୪ଟି ଆସନ ଜିତିଥିବାବେଳେ ବିଆରଏସ ୩୭.୪% ଭୋଟ୍ ପାଇ ୩୯ଟି ଆସନ ପାଇଥିଲା। ମାତ୍ର ୨% ର ପାର୍ଥକ୍ୟ ହେତୁ ୨୫ଟି ଆସନର ବ୍ୟବଧାନ ହେଲା।"
