      "body": "ରାମାଗୁଣ୍ଡମ ହେଉଛି ତେଲେଙ୍ଗାନାର ଏକମାତ୍ର ବାମପନ୍ଥୀ ଦଳର ନିର୍ବାଚନ ମଣ୍ଡଳୀ। କୋଇଲା ଖଣି ଅଞ୍ଚଳ ବାମପନ୍ଥୀ ରାଜନୀତିକୁ ଜୀବିତ ରଖିଛି।"
